SELECT icu_patients.subject_id, icu_patients.hadm_id, rr.rr_value, COUNT(DISTINCT CASE WHEN rr.rr_value < 12 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS rr_lt12, COUNT(DISTINCT CASE WHEN rr.rr_value BETWEEN 12 AND 20 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS rr_12_20, COUNT(DISTINCT CASE WHEN rr.rr_value BETWEEN 21 AND 29 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS rr_21_29, COUNT(DISTINCT CASE WHEN rr.rr_value >= 30 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS rr_ge30, COUNT(DISTINCT CASE WHEN rr.rr_value < 12 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS stroke_lt12, COUNT(DISTINCT CASE WHEN rr.rr_value BETWEEN 12 AND 20 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS stroke_12_20, COUNT(DISTINCT CASE WHEN rr.rr_value BETWEEN 21 AND 29 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS stroke_21_29, COUNT(DISTINCT CASE WHEN rr.rr_value >= 30 THEN rr.rr_value END)::FLOAT / NULLIF(COUNT(DISTINCT rr.rr_value), 0) AS stroke_ge30 FROM rr JOIN icu_patients ON rr.subject_id = icu_patients.subject_id JOIN female_patients ON icu_patients.subject_id = female_patients.subject_id JOIN age_range ON icu_patients.subject_id = age_range.subject_id WHERE icu_patients.hadm_id = rr.hadm_id GROUP BY icu_patients.subject_id, icu_patients.hadm_id, rr.rr_value;